class A { x = 1; constructor(f: boolean) { if (f) return; this.x = 2; } }
class P { y = 3; constructor(f: boolean) { if (f) { return; } this.y = 4; } }
class Dd extends P { z = 9; constructor(f: boolean) { super(f); if (f) return; this.z = 10; } }
function main(): void { console.log(JSON.stringify(new A(true)), JSON.stringify(new A(false))); console.log(JSON.stringify(new Dd(true)), JSON.stringify(new Dd(false))); }
